Ltac showpc := match goal with |- evt _ _ (MS _ _ ?pc _ _ _ _) => idtac "PC:" pc end.

Definition exit_prefix_post (sp gp tp s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo code : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 0xea308) (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 (Z_to_bv 64 code) s1
                  a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xefea4) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 320, bv_unsigned sp); (0x6600b8, 0x6600bc); (0x65fe98, 0x65feb0); (0x109610, 0x109611);
              (0x1095c0, 0x1095c8); (0x10a530, 0x10a538); (XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI);
              (0x63f302, 0x63f304); (0x63f300, 0x63f302)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp + -16).

Lemma exit_prefix_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo code tid : Z) (fin : byte) (p1 p2 : list byte) (cdt thr sec : byte) (tm1 : word)
    (o1 o2 o3 o4 : byte) (flag dso : word),
  a0 = Z_to_bv 64 code -> tp = Z_to_bv 64 0x63fe48 -> 0 <= code < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 320 -> 0x800c0000 <= lo ->
  rw_cells asegs m 0x63fda0 [C4 (Z_to_bv 64 tid)] -> 1 <= tid < 2^31 ->
  rw_cells asegs m 0x65fe98 (atexit_cells fin p1 p2 1 0x65feb0 0 0xea248) ->
  rw_cells asegs m 0x65ffb8 [C8 (Z_to_bv 64 0x8591c)] ->
  rw_cells asegs m 0x6600b8 [C4 (Z_to_bv 64 0)] ->
  rw_cells asegs m 0x6600d8 [C1 cdt; C1 thr; C1 sec; C1 (Z_to_bv 8 0); C4 tm1] ->
  ro_cells asegs m 0x19eb20 [C1 (Z_to_bv 8 0)] ->
  ro_cells asegs m 0xfa6d0 [C8 (Z_to_bv 64 0x96974); C8 (Z_to_bv 64 0x44bac)] ->
  ro_cells asegs m 0xfe818 [C8 (Z_to_bv 64 0xfa6e0); C8 (Z_to_bv 64 0xfa6d0)] ->
  ro_cells asegs m 0xfdae0 [C8 (Z_to_bv 64 0xea180); C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0xff860 [C8 dso] ->
  ro_cells asegs m 0xfe790 [C8 (Z_to_bv 64 0x102520); C8 (Z_to_bv 64 0x1095a0)] ->
  rw_cells asegs m 0x109610 [C1 (Z_to_bv 8 0)] ->
  rw_cells asegs m 0x1095c0 [C8 flag] -> bv_unsigned flag <> 0 ->
  unreg_got m ->
  ro_cells asegs m 0x10a490 [C4 (Z_to_bv 64 1)] ->
  rw_cells asegs m 0x10a530 [C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x10cc78 [C8 (Z_to_bv 64 0x7fff8000)] ->
  rw_cells asegs m 0x10d958 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x10c4dc [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x19e820 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0xff9e0 [C8 (Z_to_bv 64 0xf424c)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  gds_at m 0x102520 asan_gds ->
  rw_cells asegs m 0x63f302 [C1 o1] -> rw_cells asegs m 0x63f300 [C1 o2] -> rw_cells asegs m 0x63f301 [C1 o3] -> rw_cells asegs m 0x63f303 [C1 o4] ->
  mem_inv asegs m ->
  evt asegs (exit_prefix_post sp gp tp s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo code m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
